-- Flashcard top-up: Economics|AQA|alevel — brings each topic up to 30 cards.
-- Generated by scripts/build-flashcard-topup.js from flashcards/topup/src/economics-aqa-alevel.txt
-- Safe to re-run: skips fronts already present and never takes a topic past 30.
WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'What is scarcity?', 'The situation where unlimited wants exceed the finite resources available to satisfy them.', 1),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'What are the three basic economic questions?', 'What to produce, how to produce it, and for whom to produce it.', 2),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'What is the difference between a free good and an economic good?', 'A free good has no opportunity cost because it is not scarce (e.g. air); an economic good is scarce and has an opportunity cost.', 3),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'What does a movement along a PPF show?', 'A reallocation of resources from producing one good to another, showing the opportunity cost.', 4),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'What causes an inward shift of the PPF?', 'A fall in the quantity or quality of resources, e.g. natural disasters, war or emigration of skilled workers.', 5),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'What is productive efficiency on a PPF?', 'Any point on the frontier, where resources are fully and efficiently used.', 6),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'What is the difference between renewable and non-renewable resources?', 'Renewable resources replenish naturally (solar energy, fish stocks if managed); non-renewable resources are finite (oil, coal).', 7),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'What is the role of the entrepreneur?', 'They organise the other factors of production and take risks in the hope of making a profit.', 8),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'What are value judgements?', 'Opinions based on personal beliefs about what ought to be, rather than facts; they underpin normative statements.', 9),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'What is the advantage of a free market economy?', 'Efficient allocation through the price mechanism, consumer choice, incentives for innovation, and less bureaucracy.', 10),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'What is a disadvantage of a command economy?', 'Lack of incentives, inefficient allocation due to missing price signals, shortages and limited consumer choice.', 11),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'Why is money needed in a specialised economy?', 'It removes the need for a double coincidence of wants in barter, making exchange easier.', 12),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'What is the role of the state in a mixed economy?', 'Providing public goods, correcting market failures, redistributing income, and regulating markets.', 13),
  ('Economics', 'AQA', 'alevel', '3.1.1', 'Economic Problem & Methodology', 'How do economists use the scientific method?', 'They form hypotheses, build models, test them against data and refine them, although controlled experiments are rarely possible.', 14),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'What is rational economic behaviour in the traditional model?', 'Consumers aim to maximise utility, firms maximise profit, and governments maximise social welfare, all with full information.', 1),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'What is the marginal utility per pound?', 'The marginal utility of a good divided by its price; consumers maximise utility when it is equal across all goods.', 2),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'Why does asymmetric information cause the "market for lemons" problem?', 'Sellers know more about quality than buyers; buyers offer average prices, so good-quality sellers leave the market.', 3),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'What is adverse selection?', 'A situation where one party with hidden information is more likely to take part in a transaction, e.g. high-risk people buying insurance.', 4),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'What is the difference between System 1 and System 2 thinking?', 'System 1 is fast, automatic and intuitive; System 2 is slow, deliberate and analytical (Kahneman).', 5),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'What are heuristics?', 'Mental shortcuts or rules of thumb people use to make quick decisions, which can lead to biases.', 6),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'What is social norms'' influence on behaviour?', 'People tend to behave in line with what others do or approve of, which can be used in nudges (e.g. telling people most neighbours pay taxes on time).', 7),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'What is altruism and how does it challenge traditional theory?', 'Acting to benefit others at personal cost, contradicting the assumption of self-interested utility maximisation.', 8),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'What is the ultimatum game evidence about fairness?', 'Responders often reject low offers even though accepting would make them better off, showing people value fairness.', 9),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'What is default choice?', 'Setting the option that happens if people make no active decision, e.g. automatic enrolment in workplace pensions.', 10),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'What is restricted choice in behavioural policy?', 'Limiting the number of options available to make decisions easier, e.g. limiting the number of energy tariffs.', 11),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'What is mandated choice?', 'Requiring people to make an active decision, e.g. asking people whether they want to be organ donors when applying for a licence.', 12),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'Why might nudges be criticised?', 'They can be seen as manipulative or paternalistic, effects may be small or temporary, and they may not work for everyone.', 13),
  ('Economics', 'AQA', 'alevel', '3.1.2', 'Individual Economic Decision Making', 'Why does present bias lead to under-saving for pensions?', 'People overvalue immediate consumption compared with future benefits, so they save too little for retirement.', 14),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'What is the income effect of a price fall?', 'A fall in price increases consumers'' real income, so they can buy more of the good (if normal).', 1),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'What is the substitution effect of a price fall?', 'The good becomes relatively cheaper than substitutes, so consumers switch towards it.', 2),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'What is a Giffen good?', 'An inferior good where the income effect outweighs the substitution effect, so demand rises when price rises (an upward-sloping demand curve).', 3),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'What is a Veblen good?', 'A luxury good where higher prices increase demand because it is a status symbol.', 4),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'What does a PED of zero mean?', 'Perfectly inelastic demand: quantity demanded does not change when price changes.', 5),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'What does an infinitely elastic demand curve look like?', 'Horizontal: any rise in price causes quantity demanded to fall to zero.', 6),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'What are the determinants of PES?', 'Spare capacity, stock levels, time period, ease of factor substitution, and the production time.', 7),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'What is derived demand?', 'Demand for a good or factor of production that arises from demand for another good it helps produce, e.g. steel for cars.', 8),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'What is composite demand?', 'When a good is demanded for more than one use, e.g. milk for drinking, cheese and butter.', 9),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'What is joint supply?', 'When producing one good also produces another, e.g. beef and leather.', 10),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'What happens to price and quantity when supply increases?', 'Price falls and quantity rises (the supply curve shifts right).', 11),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'What is the incidence of a subsidy?', 'The share of the subsidy benefit received by consumers (lower price) and by producers (higher price received); it depends on elasticities.', 12),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'What is excess demand?', 'When quantity demanded exceeds quantity supplied at a given price (below equilibrium), creating a shortage.', 13),
  ('Economics', 'AQA', 'alevel', '3.1.3', 'Price Determination', 'What is the rationing function of the price mechanism?', 'Rising prices ration scarce goods to those most willing and able to pay.', 14),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'What is the difference between the short run and the long run?', 'In the short run at least one factor of production is fixed; in the long run all factors are variable.', 1),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'What is the relationship between MC and AC?', 'When MC is below AC, AC falls; when MC is above AC, AC rises; MC cuts AC at its minimum point.', 2),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'Why does the long-run average cost curve fall at first?', 'Because of economies of scale as the firm increases all its inputs.', 3),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'What are technical economies of scale?', 'Cost savings from using larger, more efficient machinery and production techniques, e.g. mass production lines.', 4),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'What are purchasing economies of scale?', 'Large firms can buy inputs in bulk at lower unit prices.', 5),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'What are financial economies of scale?', 'Large firms can borrow money more cheaply because they are seen as less risky.', 6),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'What causes diseconomies of scale?', 'Communication problems, coordination difficulties, and lower worker motivation as the firm grows too large.', 7),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'What is the minimum efficient scale?', 'The lowest level of output at which long-run average cost is minimised.', 8),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'What is the relationship between AR and the demand curve?', 'The average revenue curve is the firm''s demand curve because AR equals price.', 9),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'What happens to TR when MR is zero?', 'Total revenue is at its maximum.', 10),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'What is a sunk cost?', 'A cost that has already been incurred and cannot be recovered, so it should not affect future decisions.', 11),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'What is dynamic efficiency?', 'Efficiency over time through investment in innovation, research and development, and new technology.', 12),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'What is technological change''s effect on costs?', 'It can reduce average costs (shifting cost curves down) through new production methods and create new products.', 13),
  ('Economics', 'AQA', 'alevel', '3.1.4', 'Production Costs & Revenue', 'What is invention versus innovation?', 'Invention is creating a new idea or product; innovation is turning it into a commercially successful product or process.', 14),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'What is a price taker?', 'A firm that must accept the market price because it is too small to influence it (in perfect competition).', 1),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'What is a price maker?', 'A firm with market power that can set its own price, e.g. a monopolist.', 2),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'What does the long-run equilibrium of monopolistic competition look like?', 'Normal profit is made, with AR tangent to AC; the firm has excess capacity and is not productively or allocatively efficient.', 3),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'What is a barrier to entry?', 'Anything that makes it difficult for new firms to enter a market, e.g. economies of scale, legal barriers or brand loyalty.', 4),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'What is limit pricing?', 'Setting a price low enough to deter new firms from entering the market.', 5),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'What is predatory pricing?', 'Setting prices below cost to drive competitors out of the market, then raising prices afterwards.', 6),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'What is a cartel?', 'A formal agreement between firms to fix prices or output to act like a monopoly; illegal in the UK and EU.', 7),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'What is tacit collusion?', 'Firms coordinating their behaviour without a formal agreement, e.g. following a price leader.', 8),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'What is game theory?', 'The study of strategic decision-making where each player''s outcome depends on the actions of others.', 9),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'What is a Nash equilibrium?', 'An outcome where no player can improve their position by changing their strategy, given the other players'' strategies.', 10),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'What is a contestable market?', 'A market with low barriers to entry and exit and no sunk costs, so the threat of entry keeps prices close to competitive levels.', 11),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'What is first-degree price discrimination?', 'Charging each consumer the maximum price they are willing to pay, removing all consumer surplus.', 12),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'What is third-degree price discrimination?', 'Charging different prices to different groups of consumers based on their elasticities, e.g. student and peak/off-peak fares.', 13),
  ('Economics', 'AQA', 'alevel', '3.1.5', 'Competitive & Concentrated Markets', 'Why might a monopoly be dynamically efficient?', 'Supernormal profits can fund research and development, leading to innovation and lower costs over time.', 14),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'What is the marginal physical product of labour?', 'The extra output produced by employing one more worker.', 1),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'Why does the supply curve of labour to an industry slope upwards?', 'Higher wages attract workers from other industries and draw more people into the labour force.', 2),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'What is the backward-bending supply curve of labour?', 'At high wage rates the income effect outweighs the substitution effect, so individuals choose more leisure and supply fewer hours.', 3),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'What are non-monetary factors affecting labour supply?', 'Job satisfaction, working conditions, location, hours, status and training opportunities.', 4),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'What is occupational immobility?', 'Workers find it difficult to move between jobs because they lack the necessary skills or qualifications.', 5),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'What is geographical immobility?', 'Workers find it difficult to move to where jobs are, due to housing costs, family ties or lack of information.', 6),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'What is a wage differential?', 'The difference in wages between different workers, occupations or regions.', 7),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'Why are wage differentials useful?', 'They signal where labour is needed and encourage workers to acquire skills and move to more productive jobs.', 8),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'What is discrimination in the labour market?', 'Treating workers differently based on characteristics such as gender, race or age, rather than productivity.', 9),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'How does discrimination affect the demand for labour?', 'Employers undervalue the MRP of discriminated groups, so their demand curve shifts left, lowering wages and employment.', 10),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'What is a bilateral monopoly?', 'A market with a monopsony employer and a monopoly seller of labour (trade union); wages depend on bargaining power.', 11),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'What is the gig economy?', 'A labour market with many short-term, flexible contracts or freelance work, often through apps.', 12),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'What is the impact of migration on the labour market?', 'It increases labour supply, which may lower wages in some sectors but fills skill shortages and increases output.', 13),
  ('Economics', 'AQA', 'alevel', '3.1.6', 'The Labour Market', 'What is a zero-hours contract?', 'An employment contract with no guaranteed minimum hours, offering flexibility but income insecurity.', 14),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'What are the main sources of income?', 'Wages, rent, interest, profit and state benefits.', 1),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'What is the difference between marketable and non-marketable wealth?', 'Marketable wealth can be sold (e.g. property and shares); non-marketable wealth cannot (e.g. pension rights).', 2),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'How does inheritance affect wealth inequality?', 'Wealth is passed down generations, concentrating it in some families.', 3),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'What is the impact of progressive taxation on inequality?', 'Higher earners pay a larger proportion of income in tax, reducing income inequality.', 4),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'What are transfer payments?', 'Payments from the government that don''t involve exchange of goods or services, e.g. benefits and pensions.', 5),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'Why might some inequality be desirable?', 'It provides incentives to work hard, take risks and gain skills, which can promote growth.', 6),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'What are the consequences of high inequality?', 'Social tension, poorer health outcomes, lower social mobility, and reduced consumer spending.', 7),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'What is social mobility?', 'The ability of individuals to move between social or income groups over their lifetime or between generations.', 8),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'What is the national living wage intended to achieve?', 'Reducing in-work poverty and raising the incomes of low-paid workers.', 9),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'How can education reduce inequality?', 'It improves skills and productivity, raising earning potential and increasing social mobility.', 10),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'What are the causes of poverty?', 'Unemployment, low wages, ill health, old age, single-parent families, and low skills.', 11),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'What is fuel poverty?', 'Being unable to afford to heat a home adequately at reasonable cost.', 12),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'What is the difference between horizontal and vertical equity?', 'Horizontal equity: people in the same circumstances are treated the same. Vertical equity: people with greater ability to pay pay more.', 13),
  ('Economics', 'AQA', 'alevel', '3.1.7', 'Income Distribution, Poverty & Inequality', 'What is the relationship between inequality and economic growth?', 'Mixed: some inequality can incentivise growth, but very high inequality may reduce demand, human capital and stability.', 14),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'What is a positive externality?', 'A benefit to third parties that isn''t reflected in the market price, e.g. education or vaccinations.', 1),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'Why are merit goods underconsumed?', 'Consumers undervalue their private benefit due to imperfect information, and positive externalities are ignored.', 2),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'Why are demerit goods overconsumed?', 'Consumers underestimate their private costs due to imperfect information, and negative externalities are ignored.', 3),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'What is a quasi-public good?', 'A good that has some public good characteristics but isn''t purely non-rival or non-excludable, e.g. roads.', 4),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'What is the problem of missing markets?', 'Public goods may not be provided at all by the free market because of the free-rider problem.', 5),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'What is the tragedy of the commons?', 'Common resources that are rival but non-excludable are overused and depleted, e.g. overfishing.', 6),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'What is a buffer stock scheme?', 'A government buys surplus produce when prices are low and sells when prices are high to stabilise prices.', 7),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'Why are property rights important for externalities?', 'Clear property rights allow parties to negotiate over externalities (Coase theorem), reducing the need for intervention.', 8),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'What is the difference between allocative inefficiency and inequity in market failure?', 'Allocative inefficiency means resources are misallocated; inequity means an unfair distribution of income or wealth.', 9),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'What is the role of the Competition and Markets Authority?', 'It investigates mergers, cartels and anti-competitive practices to protect consumers and promote competition.', 10),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'What is regulation of natural monopolies using price caps?', 'The regulator sets RPI − X price caps, forcing firms to make efficiency savings.', 11),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'What are the problems of state provision?', 'Lack of competition, inefficiency, high costs to taxpayers, and political interference.', 12),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'What is the information problem in setting a Pigouvian tax?', 'It is difficult to measure the monetary value of an externality accurately, so the tax may be too high or too low.', 13),
  ('Economics', 'AQA', 'alevel', '3.1.8', 'Market Failure & Government Intervention', 'What is a pollution tax''s advantage over regulation?', 'It gives firms an incentive to reduce pollution at least cost and generates revenue.', 14),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'What is the difference between a recession and a depression?', 'A recession is two consecutive quarters of negative GDP growth; a depression is a very deep and prolonged recession.', 1),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'What is the claimant count measure of unemployment?', 'The number of people claiming unemployment-related benefits.', 2),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'What is the Labour Force Survey measure of unemployment?', 'The ILO measure: people without a job who are actively seeking work and available to start within two weeks.', 3),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'What is underemployment?', 'People working fewer hours than they want, or in jobs below their skill level.', 4),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'What is the capital account of the balance of payments?', 'It records capital transfers and the purchase or sale of non-produced, non-financial assets.', 5),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'What is the financial account?', 'It records flows of investment: direct investment, portfolio investment and changes in reserves.', 6),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'What is a current account deficit?', 'When the value of imports of goods, services and income flows exceeds exports.', 7),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'What is national income?', 'The total value of goods and services produced by an economy over a period, measured by output, income or expenditure.', 8),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'How is GDP measured by expenditure?', 'C + I + G + (X − M).', 9),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'What is the effect of inflation on real incomes?', 'If prices rise faster than nominal incomes, real incomes fall, reducing purchasing power.', 10),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'How is a real value calculated from nominal?', 'Real value = nominal value ÷ price index × 100.', 11),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'What is well-being and how is it measured?', 'Quality of life, measured by surveys of life satisfaction and indicators such as health, education and environment.', 12),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'What are the limitations of using GDP to compare countries?', 'Differences in the hidden economy, income distribution, currency values, and non-market production.', 13),
  ('Economics', 'AQA', 'alevel', '3.2.1', 'Measurement of Macroeconomic Performance', 'What is the base year in an index?', 'The year set equal to 100, used as the reference point for comparing other years.', 14),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'What is the circular flow of income?', 'A model showing income flowing between households and firms, with injections and withdrawals.', 1),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'What is the marginal propensity to consume?', 'The proportion of an extra pound of income that is spent on consumption.', 2),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'What is the marginal propensity to withdraw?', 'The proportion of extra income saved, taxed or spent on imports (MPS + MPT + MPM).', 3),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'What is the wealth effect?', 'Rising asset prices (houses, shares) make people feel wealthier and increase consumption.', 4),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'What is the interest rate effect on AD?', 'Higher interest rates increase the cost of borrowing and reward saving, reducing consumption and investment.', 5),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'How does government spending affect AD?', 'An increase directly raises AD, as G is a component of AD, and has multiplier effects.', 6),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'What is a negative output gap?', 'When actual GDP is below potential GDP, with spare capacity and unemployment.', 7),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'What is a positive output gap?', 'When actual GDP is above potential, causing inflationary pressure.', 8),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'What happens when AD rises on a classical AS model in the long run?', 'Only the price level rises; output returns to the full-employment level on the vertical LRAS.', 9),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'What causes SRAS to shift left?', 'Higher costs of production, e.g. higher wages, raw material prices or taxes on production.', 10),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'What is the relationship between investment and interest rates?', 'Higher interest rates increase the cost of borrowing, making fewer investment projects profitable.', 11),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'What role do expectations play in macroeconomics?', 'Expectations of future income, prices and profits influence consumption and investment decisions now.', 12),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'What is the difference between the classical and Keynesian views of unemployment?', 'Classical: unemployment is voluntary or caused by market rigidities, and markets self-correct. Keynesian: demand deficiency can cause prolonged unemployment.', 13),
  ('Economics', 'AQA', 'alevel', '3.2.2', 'How the Macroeconomy Works', 'What is equilibrium national income?', 'The level of output where AD equals AS, or where injections equal withdrawals.', 14),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'What is frictional unemployment?', 'Short-term unemployment while people move between jobs.', 1),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'What is structural unemployment?', 'Unemployment caused by a mismatch between workers'' skills or location and available jobs, often due to industrial decline.', 2),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'What is cyclical (demand-deficient) unemployment?', 'Unemployment caused by a lack of aggregate demand during a recession.', 3),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'What is seasonal unemployment?', 'Unemployment caused by seasonal changes in demand, e.g. tourism or agriculture.', 4),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'What is the natural rate of unemployment?', 'The rate of unemployment when the labour market is in equilibrium, made up of frictional and structural unemployment.', 5),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'What is the sustainable rate of growth?', 'Growth that can be maintained without creating inflation or harming future generations, in line with potential output.', 6),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'What are the environmental costs of growth?', 'Pollution, resource depletion, and climate change.', 7),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'What is stagflation?', 'A combination of high inflation, high unemployment and low or negative growth, e.g. from a supply shock.', 8),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'What are the benefits of low and stable inflation?', 'Certainty for firms and consumers, encouraging investment, and maintaining international competitiveness.', 9),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'What is menu cost?', 'The cost to firms of changing prices frequently during inflation.', 10),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'What is shoe-leather cost?', 'The time and effort spent minimising cash holdings during high inflation.', 11),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'What is fiscal drag?', 'When tax thresholds don''t rise with inflation, more people are pulled into higher tax brackets.', 12),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'What is a conflict between macroeconomic objectives?', 'E.g. faster growth may increase inflation and worsen the current account; reducing inflation may raise unemployment.', 13),
  ('Economics', 'AQA', 'alevel', '3.2.3', 'Economic Performance', 'What is the difference between the short-run and long-run Phillips curve views?', 'Short run: a trade-off between inflation and unemployment. Long run: vertical at the natural rate, so no trade-off.', 14),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'What is a financial intermediary?', 'An institution, such as a bank, that channels funds from savers to borrowers.', 1),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'What is an investment bank?', 'A bank that deals in financial markets, helps firms raise capital, and trades securities.', 2),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'What is the relationship between bank liquidity and profitability?', 'Holding more liquid assets reduces risk but earns lower returns; lending more earns higher returns but increases risk.', 3),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'What is the Monetary Policy Committee?', 'A Bank of England committee that sets Bank Rate to meet the government''s inflation target of 2% CPI.', 4),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'What is the inflation target in the UK?', '2% CPI inflation, with a letter required from the Governor if it is more than 1 percentage point either side.', 5),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'What is forward guidance?', 'The central bank''s communication about the likely future path of interest rates to influence expectations.', 6),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'How does a rise in Bank Rate affect the exchange rate?', 'It attracts hot money inflows, increasing demand for the pound and causing it to appreciate.', 7),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'What is the lender of last resort?', 'The central bank''s role of lending to banks in difficulty to prevent a collapse of the banking system.', 8),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'What is systemic risk?', 'The risk that the failure of one financial institution causes a chain reaction throughout the financial system.', 9),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'What is the Financial Policy Committee?', 'A Bank of England committee responsible for macroprudential regulation, identifying and reducing systemic risks.', 10),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'What is the Prudential Regulation Authority?', 'Part of the Bank of England, it regulates banks and insurers to ensure they are safe and sound.', 11),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'What is the Financial Conduct Authority?', 'The regulator responsible for conduct in financial markets, protecting consumers and market integrity.', 12),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'What is the capital ratio?', 'A bank''s capital as a proportion of its risk-weighted assets, acting as a buffer against losses.', 13),
  ('Economics', 'AQA', 'alevel', '3.2.4', 'Financial Markets & Monetary Policy', 'What is market failure in the financial sector?', 'Asymmetric information, moral hazard, speculation and bubbles, market rigging, and externalities from bank failures.', 14),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'What is a balanced budget?', 'When government spending equals tax revenue.', 1),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'What is contractionary fiscal policy?', 'Reducing government spending or raising taxes to reduce aggregate demand and inflation.', 2),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'What is discretionary fiscal policy?', 'Deliberate changes in government spending or taxation to influence the economy.', 3),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'What is the difference between current and capital spending?', 'Current spending is on day-to-day costs (wages, benefits); capital spending is on investment (infrastructure).', 4),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'Why might a large national debt be a problem?', 'High interest payments, reduced fiscal flexibility, possible loss of confidence, and burden on future generations.', 5),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'What is austerity?', 'Policies of reducing government spending and/or raising taxes to reduce a budget deficit.', 6),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'What is the impact of lower income tax on labour supply?', 'It increases incentives to work and may increase labour supply, although income effects may offset this.', 7),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'How can education and training act as a supply-side policy?', 'They improve human capital and labour productivity, shifting LRAS to the right.', 8),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'What is deregulation as a supply-side policy?', 'Removing rules and barriers to entry to increase competition and efficiency.', 9),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'What is privatisation?', 'Transferring ownership of state-owned firms to the private sector to improve efficiency through the profit motive.', 10),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'What are the time lags of supply-side policies?', 'They often take years to have an effect, e.g. education reforms.', 11),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'What is the effect of increasing infrastructure spending?', 'It raises AD in the short run and increases productive capacity (LRAS) in the long run.', 12),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'What is the effect of a lower corporation tax?', 'It may increase investment and attract foreign firms, raising productive capacity.', 13),
  ('Economics', 'AQA', 'alevel', '3.2.5', 'Fiscal & Supply-Side Policies', 'What is the difference between fiscal and monetary policy''s impact on distribution?', 'Fiscal policy can target specific groups through taxes and benefits; monetary policy affects savers and borrowers.', 14),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'What is the terms of trade?', 'Index of export prices ÷ index of import prices × 100.', 1),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'What happens if the terms of trade improve?', 'Each unit of exports buys more imports, although export competitiveness may fall.', 2),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'What is a free trade area?', 'Member countries remove trade barriers between themselves but keep their own external tariffs, e.g. USMCA.', 3),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'What is a customs union?', 'A free trade area with a common external tariff on non-members.', 4),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'What is a single market?', 'A customs union with free movement of goods, services, labour and capital, plus common regulations.', 5),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'What is monetary union?', 'A single market with a common currency and monetary policy, e.g. the eurozone.', 6),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'What is an appreciation of the exchange rate?', 'An increase in the value of a currency relative to others, making exports dearer and imports cheaper.', 7),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'What factors cause a currency to depreciate in a floating system?', 'Lower interest rates, higher inflation, a current account deficit, or loss of confidence.', 8),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'What is the role of the World Trade Organization?', 'Promoting free trade, negotiating agreements and settling trade disputes between members.', 9),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'What is dumping?', 'Selling goods in foreign markets below cost price, which can harm domestic producers.', 10),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'What is an infant industry argument?', 'New industries need temporary protection until they can compete with established foreign firms.', 11),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'What is the impact of globalisation on developing countries?', 'Access to markets, FDI, jobs and technology, but also exploitation, inequality and environmental damage.', 12),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'What is the difference between economic growth and economic development?', 'Growth is an increase in real GDP; development is a broader improvement in living standards, including health and education.', 13),
  ('Economics', 'AQA', 'alevel', '3.2.6', 'The International Economy', 'What is a primary product dependency?', 'Relying on exports of commodities, whose prices are volatile, which makes incomes unstable and can hinder development.', 14)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Economics' AND exam_board = 'AQA' AND level = 'alevel'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
